from __future__ import annotations

from docich.hanjuku_speedrun.hanjuku.judgment import battle as rules


def test_missing_card_is_not_remaining():
    cur = {'cards_selected': ['クースカン', 'イッテツーン'],
           'cards_used': [], 'cards_missing': ['クースカン']}
    assert rules._retreat_remaining_cards(cur) == ['イッテツーン']
    # 不在が確認できた札だけなら、退却前の使用試行もしない。
    assert rules._retreat_cards_to_spend({'cards_selected': ['クースカン'],
                                          'cards_used': [],
                                          'cards_missing': ['クースカン']}) is False
    # 不在の記録が無ければ従来どおり残り札として扱う。
    assert rules._retreat_cards_to_spend({'cards_selected': ['クースカン'],
                                          'cards_used': []}) is True
